window.docContents[14].resolve({"/Terms/#termsOverview":{"contents":"Cvc.lean exposes two API-s for terms: Typed and Untyped. The former provides very strong static\nguarantees by strongly-typing terms; the latter does not but is more flexible, allowing in\nparticular to build lists/arrays of terms of different sorts.\n\nNB: cvc.lean enforces type-safety through definition irreducibility, which means you need to use\n\nLean's module system to get any of its benefits.\n\n\n\n\n\n","context":"Cvc.lean -- High-Level CVC5 API","header":"3. Terms","id":"/Terms/#termsOverview"}});